    File f = new File(makeCachePath(fileLocation));
    if (cachePathPolicy == CachePathPolicy.NestedDirectory){
        File dir = f.getParentFile();
        if (!dir.exists() && !dir.mkdirs())
            cacheLog.warn("Cant create directories for file " + dir.getPath());
    }
    return f;
}

